cd /testbed && python - <<'PY'
from pathlib import Path
path = Path('sklearn/linear_model/logistic.py')
text = path.read_text()
old = """                best_indices = np.argmax(scores, axis=1)
                if self.multi_class == 'ovr':
                    w = np.mean([coefs_paths[i, best_indices[i], :]
                                 for i in range(len(folds))], axis=0)
                else:
                    w = np.mean([coefs_paths[:, i, best_indices[i], :]
                                 for i in range(len(folds))], axis=0)
"""
new = """                best_indices = np.argmax(scores, axis=1)
                # Use the resolved value of `multi_class` (as returned by
                # _check_multi_class) rather than the user provided
                # `self.multi_class` parameter. The latter can be 'auto' or
                # 'warn' while the internal computation and the shapes of
                # `scores` / `coefs_paths` correspond to the resolved setting.
                if multi_class == 'ovr':
                    w = np.mean([coefs_paths[i, best_indices[i], :]
                                 for i in range(len(folds))], axis=0)
                else:
                    w = np.mean([coefs_paths[:, i, best_indices[i], :]
                                 for i in range(len(folds))], axis=0)
"""
if old not in text:
    raise SystemExit('Target snippet not found; aborting')
path.write_text(text.replace(old, new))
print('Patched', path)
PY

